const results = [];

for (const item of $input.all()) {
  if (!item.binary) continue;

  for (const [key, attachment] of Object.entries(item.binary)) {
    const mimeType = attachment.mimeType || "";

    if (mimeType !== "application/pdf") continue;

    results.push({
  json: {
    ...item.json,
    attachmentName: attachment.fileName || key,
    attachmentId: results.length,
  },
  binary: {
    data: attachment,
  },
});
  }
}

return results;

const results = [];

for (const item of $input.all()) {
  if (!item.binary) continue;

  for (const [key, attachment] of Object.entries(item.binary)) {
    const mimeType = attachment.mimeType || "";

    if (mimeType !== "application/pdf") continue;

    results.push({
  json: {
    ...item.json,
    attachmentName: attachment.fileName || key,
    attachmentId: results.length,
  },
  binary: {
    data: attachment,
  },
});
  }
}

return results;

const items = $input.all();

const combinedText = items
  .map(item => item.json.text)
  .filter(text => text && text.trim())
  .join("\n\n--- NEXT DOCUMENT ---\n\n");

return [
  {
    json: {
      text: combinedText,
      document_count: items.length
    }
  }
];

const results = [];

for (const item of $input.all()) {
  const images = item.json.images || [];

  images.forEach((image, index) => {
    results.push({
      json: {
        filename: item.json.filename,
        page_number: index + 1,
        imageBase64: image
      }
    });
  });
}

return results;

const items = $input.all();

const email = items.find(item => item.json.id && item.json.threadId)?.json;
const modelResponse = items.find(item => item.json.message?.content)?.json;

if (!email) {
  throw new Error("Missing email metadata");
}
if (!modelResponse) {
  console.log("Missing invoice extraction");
  return [];
}

const extracted = JSON.parse(modelResponse.message.content);

return [
  {
    json: {
      channel: "pdf",

      email: {
        gmail_id: email.id,
        thread_id: email.threadId,
        message_id: email.messageId,
        subject: email.subject,
        date: email.date,

        from: email.from,
        to: email.to,

        body: {
          text: email.text,
          html: email.html,
          text_as_html: email.textAsHtml
        },

        labels: email.labelIds,

        headers: email.headers
      },

      extraction: {
        model: modelResponse.model,
        created_at: modelResponse.created_at,
        done: modelResponse.done,
        done_reason: modelResponse.done_reason
      },

      invoices: extracted.invoices
    }
  }
];

const items = $input.all();

// Find Gmail metadata
const email = items.find(item =>
  item.json.id && item.json.threadId
)?.json;

// Find all Ollama responses
const modelResponses = items.filter(item =>
  item.json.message?.content
);

if (!email) {
  throw new Error("Gmail metadata not found");
}

if (modelResponses.length === 0) {
  console.log("No invoice extraction responses found");
  return [];
}

// Parse and combine invoices from every response
const invoices = [];

for (const response of modelResponses) {
  const parsed = JSON.parse(response.json.message.content);

  if (Array.isArray(parsed.invoices)) {
    invoices.push(...parsed.invoices);
  }
}

return [
  {
    json: {
      channel: "img",

      email: {
        gmail_id: email.id,
        thread_id: email.threadId,
        message_id: email.messageId,
        subject: email.subject,
        date: email.date,
        from: email.from,
        to: email.to,

        body: {
          text: email.text,
          html: email.html,
          text_as_html: email.textAsHtml
        },

        labels: email.labelIds,
        headers: email.headers
      },

      extraction: {
        model: modelResponses[0].json.model,
        response_count: modelResponses.length,
        created_at: modelResponses.map(
          response => response.json.created_at
        )
      },

      invoices
    }
  }
];

