={{ ({
  invoices: $json.invoices.map(invoice => ({
    email: {
      gmail_id: $json.email.gmail_id,
      thread_id: $json.email.thread_id,
      subject: $json.email.subject,
      sender: $json.email.from?.value?.[0]?.address,
      recipient: $json.email.to?.value?.[0]?.address,
      email_date: $json.email.date
    },
    extraction: {
  ...$json.extraction,
  channel: $json.channel
    },
    invoice: {
      is_invoice: invoice.is_invoice,
      reason: invoice.reason,
      vendor_name: invoice.vendor_name,
      invoice_number: invoice.invoice_number,
      invoice_date: invoice.invoice_date,
      po_number: invoice.po_number,
      due_date: invoice.due_date,
      bill_to: invoice.bill_to,
      currency: invoice.currency,
      subtotal: Number(String(invoice.subtotal ?? "").replace(/[^\d.-]/g, "")) || 0,
      tax_amount: Number(String(invoice.tax_amount ?? "").replace(/[^\d.-]/g, "")) || 0,
      grand_total: Number(String(invoice.grand_total ?? "").replace(/[^\d.-]/g, "")) || 0,
      notes: invoice.notes
    },
    line_items: (invoice.line_items ?? []).map(line => ({
      description: line.description,
      quantity: Number(line.quantity) || 0,
      unit: line.unit,
      unit_price: Number(line.unit_price) || 0,
      line_total: Number(line.line_total) || 0
    }))
  }))
}) }}

